    info_html = "".join([f'<span class="shop-badge">{i}</span>' for i in info])

    return f"""
    <div class="shop-hero">
        {logo_html}
        <h1>{dados['nome']}</h1>
        <p><b>{dados['subtitulo']}</b></p>
        <p>{dados['descricao']}</p>
        {info_html}
    </div>
    """




