def obter_credenciais_login():
    try:
        try:
            login = st.secrets.get("login", {})
        except Exception:
            login = {}
        usuario = str(os.getenv("LOGIN_USUARIO", "") or login.get("usuario", "")).strip()
        senha = str(os.getenv("LOGIN_SENHA", "") or login.get("senha", "")).strip()
        return usuario, senha
    except Exception:
        return "", ""


