# ============================================================
# SOPHI ERP V2 — PORTAL DO CLIENTE + ARTES + IMPRESSÃO + CALENDÁRIO
# ============================================================

def garantir_portal_v2():
    garantir_portal_cliente()
    executar("""
    CREATE TABLE IF NOT EXISTS portal_eventos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        orcamento_id INTEGER,
        token TEXT,
        evento TEXT,
        descricao TEXT,
        data TEXT DEFAULT CURRENT_TIMESTAMP
    )
    """)
    executar("""
    CREATE TABLE IF NOT EXISTS portal_aprovacoes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        orcamento_id INTEGER,
        token TEXT,
        tipo TEXT DEFAULT 'Pedido',
        status TEXT DEFAULT 'Pendente',
        comentario TEXT,
        data TEXT DEFAULT CURRENT_TIMESTAMP
    )
    """)
    # Notificações internas do ERP: UM registro independente para CADA ação do cliente.
    # A coluna portal_evento_id vincula a notificação ao evento exato do Portal.
    # Isso permite que o MESMO Portal gere quantas notificações forem necessárias,
    # inclusive várias aprovações/alterações em versões diferentes da arte.
    executar("""
    CREATE TABLE IF NOT EXISTS portal_notificacoes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        orcamento_id INTEGER,
        token TEXT,
        evento TEXT NOT NULL,
        descricao TEXT,
        versao INTEGER,
        lida TEXT DEFAULT 'Não',
        data TEXT DEFAULT CURRENT_TIMESTAMP,
        portal_evento_id INTEGER,
        sync_id TEXT
    )
    """)
    # Compatibilidade com instalações anteriores: adiciona somente os campos
    # necessários, sem apagar ou alterar os dados existentes.
    try:
        _cols_notif = consultar("PRAGMA table_info(portal_notificacoes)")["name"].astype(str).tolist()
        if "versao" not in _cols_notif:
            executar("ALTER TABLE portal_notificacoes ADD COLUMN versao INTEGER")
        if "lida" not in _cols_notif:
            executar("ALTER TABLE portal_notificacoes ADD COLUMN lida TEXT DEFAULT 'Não'")
        if "data" not in _cols_notif:
            executar("ALTER TABLE portal_notificacoes ADD COLUMN data TEXT")
        if "portal_evento_id" not in _cols_notif:
            executar("ALTER TABLE portal_notificacoes ADD COLUMN portal_evento_id INTEGER")
        if "sync_id" not in _cols_notif:
            executar("ALTER TABLE portal_notificacoes ADD COLUMN sync_id TEXT")
            executar("CREATE UNIQUE INDEX IF NOT EXISTS idx_portal_notificacoes_sync_id ON portal_notificacoes(sync_id)")
    except Exception:
        pass

    # Permite que cada arte tenha sua própria aprovação/alteração quando houver várias artes no mesmo pedido.
    try:
        colunas_aprov = consultar("PRAGMA table_info(portal_aprovacoes)")["name"].astype(str).tolist()
        if "arte_id" not in colunas_aprov:
            executar("ALTER TABLE portal_aprovacoes ADD COLUMN arte_id INTEGER")
    except Exception:
        pass

    executar("""
    CREATE TABLE IF NOT EXISTS portal_artes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        orcamento_id INTEGER,
        nome_arquivo TEXT,
        caminho TEXT,
        versao INTEGER DEFAULT 1,
        status TEXT DEFAULT 'Aguardando aprovação',
        observacao TEXT,
        data TEXT DEFAULT CURRENT_TIMESTAMP
    )
    """)
    executar("""
    CREATE TABLE IF NOT EXISTS impressoras_termicas (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nome TEXT,
        modelo TEXT,
        largura TEXT DEFAULT '80 mm',
        padrao TEXT DEFAULT 'Não',
        ativo TEXT DEFAULT 'Sim'
    )
    """)


def portal_evento(orcamento_id, token, evento, descricao, versao=None):
    """
    Registra um evento do Portal e, quando for uma ação do cliente, cria
    uma NOTIFICAÇÃO NOVA e independente no ERP.

    Importante: não existe deduplicação por portal, token, evento ou versão.
    Portanto, o mesmo Portal pode gerar várias notificações ao longo do tempo:
    aprovação da versão 1, alteração, aprovação da versão 2, nova alteração,
    aprovação do pedido etc.
    """
    try:
        garantir_portal_v2()
        oid = int(orcamento_id)
        tok = str(token)
        evt = str(evento or "").strip()
        desc = str(descricao or "")
        data_evento = agora_brasil().isoformat()

        eventos_cliente = {
            "Arte aprovada",
            "Alteração de arte",
            "Pedido aprovado",
            "Pedido reprovado",
        }

        # Uma única transação grava primeiro o evento e, se for uma ação
        # do cliente, a notificação correspondente. Assim cada notificação
        # fica ligada ao ID EXATO daquele evento, mesmo usando o mesmo Portal.
        with conectar() as conn:
            cur = conn.cursor()
            cur.execute(
                "INSERT INTO portal_eventos(orcamento_id,token,evento,descricao,data) VALUES(?,?,?,?,?)",
                (oid, tok, evt, desc, data_evento),
            )
            portal_evento_id = cur.lastrowid

            if evt in eventos_cliente:
                cur.execute(
                    """
                    INSERT INTO portal_notificacoes
                        (orcamento_id, token, evento, descricao, versao, lida, data, portal_evento_id)
                    VALUES (?, ?, ?, ?, ?, 'Não', ?, ?)
                    """,
                    (
                        oid,
                        tok,
                        evt,
                        desc,
                        int(versao) if versao is not None else None,
                        data_evento,
                        int(portal_evento_id),
                    ),
                )

            conn.commit()

        # Sincroniza somente depois que a transação terminou.
        # Não há INSERT OR IGNORE nem chave de deduplicação: cada ação
        # confirmada pelo cliente gera uma nova notificação.
        if evt in eventos_cliente:
            # Canal dedicado: a notificação chega mesmo se a sincronização
            # do arquivo SQLite estiver atrasada ou em conflito.
            _notif_sync_id = _sincronizar_notificacao_portal_nuvem(
                oid, tok, evt, desc, versao, data_evento, portal_evento_id
            )

            _notif_payload = {
                "sync_id": str(_notif_sync_id or uuid.uuid4().hex),
                "orcamento_id": oid,
                "token": tok,
                "evento": evt,
                "descricao": desc,
                "versao": int(versao) if versao is not None else None,
                "data": data_evento,
                "portal_evento_id": int(portal_evento_id),
            }
            _feed_sync_id = _publicar_feed_notificacao_portal_nuvem(_notif_payload)

            # Mantém também a sincronização tradicional do ERP.
            _sync_ok = enviar_banco_para_nuvem(force=True)
            if _sync_ok is False:
                print("[PORTAL NOTIFICACAO] Banco principal não sincronizou; canal dedicado preservado.")
            if not _notif_sync_id and not _feed_sync_id:
                print("[PORTAL NOTIFICACAO] Nenhum canal remoto conseguiu publicar o evento.")

        return int(portal_evento_id)

    except Exception as _portal_evento_err:
        print(f"[PORTAL NOTIFICACAO] Falha ao gravar/sincronizar evento: {_portal_evento_err}")
        return None
    return True
def _url_notificacao_portal(notificacao_id, token):
    base = APP_URL_OFICIAL.rstrip('/')
    return f"{base}/?portal=cliente&token={token}&notificacao={int(notificacao_id)}"


def marcar_notificacao_portal_lida(notificacao_id):
    try:
        if notificacao_id:
            executar("UPDATE portal_notificacoes SET lida='Sim' WHERE id=?", (int(notificacao_id),))
            enviar_banco_para_nuvem(force=True)
    except Exception:
        pass


def mostrar_notificacoes_portal_erp():
    import urllib.parse
    """Mostra somente notificações pendentes do Portal e abre o Portal em nova guia."""
    try:
        garantir_portal_v2()
        try:
            baixar_banco_da_nuvem()
        except Exception:
            pass

        # Busca também o canal dedicado. Isso é o que garante a chegada
        # imediata quando Portal e ERP estão em sessões Railway diferentes.
        try:
            _importar_notificacoes_portal_nuvem()
        except Exception as _notif_import_err:
            print(f"[PORTAL NOTIFICACAO] Falha na atualização das notificações: {_notif_import_err}")

        notas = consultar("""
            SELECT n.*, o.cliente_nome
            FROM portal_notificacoes n
            LEFT JOIN orcamentos o ON o.id=n.orcamento_id
            WHERE COALESCE(LOWER(n.lida), 'não') <> 'sim'
            ORDER BY n.id DESC
            LIMIT 50
        """)

        qtd = len(notas) if not notas.empty else 0
        st.sidebar.markdown(
            f'<div id="sophi-notificacoes-titulo" style="margin:8px 0 6px;font-weight:900;font-size:13px;">🔔 Notificações ({qtd})</div>',
            unsafe_allow_html=True
        )

        if notas.empty:
            st.sidebar.caption("Nenhuma notificação do Portal.")
            return

        for _, nrow in notas.head(15).iterrows():
            _notif_id_btn = int(nrow["id"])
            _token_btn = str(nrow.get("token") or "")
            evento = str(nrow.get("evento") or "Atualização do Portal")
            cliente = str(nrow.get("cliente_nome") or "Cliente")
            vers = nrow.get("versao")
            vers_txt = f" · Versão {int(vers)}" if pd.notna(vers) else ""

            _portal_base_btn = APP_URL_OFICIAL.rstrip("/")
            _portal_link_btn = (
                f"{_portal_base_btn}/?portal=cliente"
                f"&token={urllib.parse.quote(_token_btn)}"
                f"&notificacao={_notif_id_btn}"
            )

            _wrapper_id = f"sophi-notif-{_notif_id_btn}"
            st.sidebar.markdown(
                f"""
                <div id="{_wrapper_id}" style="margin:7px 0 10px;">
                    <div style="font-size:11px;font-weight:800;margin-top:7px;">
                        🔔 {html.escape(evento)}{html.escape(vers_txt)}
                    </div>
                    <div style="font-size:10px;color:#aaa;margin-bottom:3px;">
                        {html.escape(cliente)}
                    </div>
                    <a href="{html.escape(_portal_link_btn, quote=True)}"
                       target="_blank"
                       rel="noopener noreferrer"
                       onclick="
                           try {{
                               this.closest('#{_wrapper_id}').style.display='none';
                               const t=document.getElementById('sophi-notificacoes-titulo');
                               if(t) {{
                                   const m=t.textContent.match(/(\\d+)/);
                                   if(m) t.textContent='🔔 Notificações ('+Math.max(0,parseInt(m[1],10)-1)+')';
                               }}
                           }} catch(e) {{}}
                       "
                       style="display:block;text-align:center;background:#050505;color:#fff;
                              padding:11px 12px;border-radius:12px;font-weight:900;font-size:11px;
                              text-decoration:none;margin:5px 0 9px;">
                        Abrir Portal deste cliente
                    </a>
                </div>
                """,
                unsafe_allow_html=True
            )
    except Exception:
        pass


def _portal_token_v2():
    try:
        return str(st.query_params.get("token", "") or "")
    except Exception:
        return ""


def _portal_contexto_v2(token):
    if not token:
        return None, None, None
    df = consultar("SELECT * FROM portal_tokens WHERE token=? AND ativo='Sim' LIMIT 1", (token,))
    if df.empty:
        return None, None, None
    t = df.iloc[0]
    ref = int(t["referencia_id"])
    if str(t["tipo"]) == "Orçamento":
        orc = consultar("SELECT * FROM orcamentos WHERE id=?", (ref,))
    else:
        op = consultar("SELECT * FROM ordens_producao WHERE id=?", (ref,))
        if op.empty or pd.isna(op.iloc[0].get("orcamento_id")):
            orc = pd.DataFrame()
        else:
            orc = consultar("SELECT * FROM orcamentos WHERE id=?", (int(op.iloc[0]["orcamento_id"]),))
    return t, orc, ref


def _portal_url_v2(orcamento_id, base_url=None):
    # URL pública oficial do Portal. Nunca usar URL antiga do Streamlit.
    base = APP_URL_OFICIAL.rstrip("/")
    token = gerar_token_portal("Orçamento", int(orcamento_id))
    return f"{base}/?portal=cliente&token={token}"


def _portal_status_v2(status):
    s = str(status or "").lower()
    if "entreg" in s: return "Entregue"
    if "saiu" in s or "entrega" in s: return "Saiu para entrega"
    if "pronto" in s: return "Pronto"
    if "produ" in s or "embala" in s: return "Em produção"
    if "pago" in s: return "Pagamento confirmado"
    if "aprov" in s or "confirm" in s: return "Pedido aprovado"
    return "Orçamento"


def _portal_etapas_v2(status):
    etapas = ["Orçamento", "Pedido aprovado", "Pagamento confirmado", "Arte", "Em produção", "Pronto", "Saiu para entrega", "Entregue"]
    atual = _portal_status_v2(status)
    mapa = {x:i for i,x in enumerate(etapas)}
    idx = mapa.get(atual, 0)
    if atual == "Em produção": idx = 4
    return [(e, i <= idx) for i,e in enumerate(etapas)]


def tela_portal_cliente_publico():
    aplicar_visual_publico_limpo()
    garantir_portal_v2()
    token = _portal_token_v2()
    try:
        _notif_id = st.query_params.get("notificacao", "")
        if _notif_id:
            marcar_notificacao_portal_lida(int(_notif_id))
    except Exception:
        pass
    t, orc, _ = _portal_contexto_v2(token)
    if t is None or orc is None or orc.empty:
        st.error("Link inválido ou pedido não encontrado.")
        st.stop()
    try:
        executar("UPDATE portal_tokens SET acessos=COALESCE(acessos,0)+1, ultimo_acesso=CURRENT_TIMESTAMP WHERE token=?", (token,))
    except Exception:
        pass
    o = orc.iloc[0]
    oid = int(o["id"])
    nome = str(o.get("cliente_nome") or "cliente")
    status = str(o.get("status") or "Orçamento")
    codigo = codigo_visual("ORC", oid, ano=datetime.now().year)
    logo = obter_config("logo_path", "")
    if logo and Path(logo).exists():
        st.image(logo, width=130)
    st.markdown(f"# Olá, {html.escape(nome)}! 🤍")
    st.caption(f"Pedido {codigo} · Portal exclusivo da Sophi Personalizados")

    # Linha do tempo
    etapas = _portal_etapas_v2(status)
    cols = st.columns(len(etapas))
    for col, (etapa, done) in zip(cols, etapas):
        with col:
            st.markdown(("🟢" if done else "⚪") + f"<br><small>{html.escape(etapa)}</small>", unsafe_allow_html=True)
    st.divider()

    total = float(o.get("total") or 0)
    c1,c2,c3,c4 = st.columns(4)
    c1.metric("Status", _portal_status_v2(status))
    c2.metric("Total", real(total))
    c3.metric("Pedido", codigo)
    data_entrega_portal=data_br_segura(o.get("data_prevista_entrega")) or "A definir"
    hora_entrega_portal=str(o.get("hora_prevista_entrega") or "").strip()
    if hora_entrega_portal:
        try:
            hora_dt=pd.to_datetime(hora_entrega_portal,errors="coerce")
            hora_entrega_portal=hora_dt.strftime("%H:%M") if pd.notna(hora_dt) else hora_entrega_portal[:5]
        except Exception:
            hora_entrega_portal=hora_entrega_portal[:5]
        data_entrega_portal=f"{data_entrega_portal} às {hora_entrega_portal}"
    c4.metric("Entrega", data_entrega_portal)

    itens = consultar("SELECT produto,categoria,quantidade,valor_unitario,desconto,total FROM orcamento_itens WHERE orcamento_id=?", (oid,))
    st.subheader("🛍️ Seu pedido")
    if itens.empty:
        st.info("Itens ainda não cadastrados.")
    else:
        st.dataframe(formatar_valores_tabela(itens), use_container_width=True, hide_index=True)

    # Pagamento sem expor custos internos
    st.subheader("💰 Pagamento")
    pago = 0.0
    try:
        for table in ["financeiro", "lancamentos_financeiros", "contas_receber"]:
            try:
                dfp = consultar(f"SELECT * FROM {table} LIMIT 1")
                if not dfp.empty:
                    cols_df = [str(x) for x in dfp.columns]
                    idcol = next((x for x in ["orcamento_id","pedido_id","referencia_id"] if x in cols_df), None)
                    valcol = next((x for x in ["valor","total","valor_pago"] if x in cols_df), None)
                    if idcol and valcol:
                        rows = consultar(f"SELECT * FROM {table} WHERE {idcol}=?", (oid,))
                        for _, r in rows.iterrows():
                            pago += float(r.get(valcol) or 0)
                        if pago: break
            except Exception:
                continue
    except Exception:
        pass
    restante = max(0.0, total-pago)
    p1,p2 = st.columns(2)
    p1.metric("Pago registrado", real(pago))
    p2.metric("Restante", real(restante))
    st.caption("Os valores exibidos ao cliente são apenas os valores do pedido; custos e margens internas nunca são exibidos.")

    # Arte
    st.subheader("🎨 Arte para aprovação")
    # Mostra todas as artes atuais do pedido, mas nunca as que foram substituídas/excluídas.
    # Assim é possível ter várias artes válidas no mesmo pedido sem deixar uma arte errada visível.
    artes = consultar("SELECT * FROM portal_artes WHERE orcamento_id=? AND COALESCE(status,'') NOT IN ('Substituída','Excluída') ORDER BY versao DESC, id DESC", (oid,))
    if artes.empty:
        st.info("A arte ainda não foi disponibilizada. Assim que a Sophi enviar, ela aparecerá aqui.")
    else:
        for _, a in artes.iterrows():
            st.markdown(f"**Versão {int(a.get('versao') or 1)} — {html.escape(str(a.get('nome_arquivo') or 'Arte'))}**")
            caminho = str(a.get("caminho") or "")
            if caminho and Path(caminho).exists():
                try:
                    arte_preview=_arte_portal_com_marca_dagua(caminho)
                    if arte_preview:
                        st.image(arte_preview,use_container_width=True)
                        st.caption("🔒 Sophi Personalizados Oficial · prévia protegida para aprovação. A arte final sem marca d’água é entregue somente após a confirmação do pedido e pagamento.")
                    else:
                        st.error("Não foi possível gerar a prévia protegida desta arte.")
                except Exception:
                    pass
            # Cada arte possui seu próprio estado de aprovação.
            aprov = consultar("SELECT * FROM portal_aprovacoes WHERE orcamento_id=? AND tipo='Arte' AND arte_id=? ORDER BY id DESC LIMIT 1", (oid, int(a['id'])))
            estado = str(aprov.iloc[0]["status"]) if not aprov.empty else str(a.get("status") or "Aguardando aprovação")
            if estado == "Aprovada":
                st.success("✅ Arte aprovada")
            elif estado == "Alteração solicitada":
                st.warning("✏️ Alteração solicitada")
            else:
                b1,b2 = st.columns(2)
                with b1:
                    if st.button("✅ APROVAR ARTE", key=f"ap_arte_{a['id']}", use_container_width=True):
                        executar("INSERT INTO portal_aprovacoes(orcamento_id,token,tipo,status,comentario,arte_id) VALUES(?,?,?,?,?,?)", (oid,token,"Arte","Aprovada","Arte aprovada pelo cliente",int(a['id'])))
                        executar("UPDATE portal_artes SET status='Aprovada' WHERE id=?", (int(a['id']),))
                        portal_evento(oid,token,"Arte aprovada","Cliente aprovou a arte.", versao=int(a.get("versao") or 1))
                        st.success("Arte aprovada com sucesso!")
                        st.rerun()
                with b2:
                    if st.button("✏️ SOLICITAR ALTERAÇÃO", key=f"alt_arte_{a['id']}", use_container_width=True):
                        st.session_state[f"alterar_arte_{a['id']}"] = True
                if st.session_state.get(f"alterar_arte_{a['id']}"):
                    comentario = st.text_area("O que deseja alterar?", key=f"coment_arte_{a['id']}")
                    if st.button("Enviar solicitação", key=f"send_alt_{a['id']}"):
                        executar("INSERT INTO portal_aprovacoes(orcamento_id,token,tipo,status,comentario,arte_id) VALUES(?,?,?,?,?,?)", (oid,token,"Arte","Alteração solicitada",comentario,int(a['id'])))
                        executar("UPDATE portal_artes SET status='Alteração solicitada', observacao=? WHERE id=?", (comentario,int(a['id'])))
                        portal_evento(oid,token,"Alteração de arte",comentario, versao=int(a.get("versao") or 1))
                        st.success("Sua solicitação foi enviada para a Sophi.")
                        st.rerun()

    # Aprovação do pedido
    st.subheader("✅ Aprovação do pedido")
    ap = consultar("SELECT * FROM portal_aprovacoes WHERE orcamento_id=? AND tipo='Pedido' ORDER BY id DESC LIMIT 1", (oid,))
    pedido_status = str(ap.iloc[0]["status"]) if not ap.empty else "Pendente"
    if pedido_status == "Aprovado":
        st.success("Pedido aprovado pelo cliente.")
    else:
        st.write("Confira os itens, valores e prazo antes de confirmar.")
        if st.button("✅ APROVAR PEDIDO", type="primary", use_container_width=True):
            executar("INSERT INTO portal_aprovacoes(orcamento_id,token,tipo,status,comentario) VALUES(?,?,?,?,?)", (oid,token,"Pedido","Aprovado","Cliente aprovou o pedido pelo portal"))
            try:
                executar("UPDATE orcamentos SET status='Aprovado' WHERE id=?", (oid,))
            except Exception: pass
            portal_evento(oid,token,"Pedido aprovado","Cliente aprovou o pedido pelo portal.")
            st.success("Pedido aprovado! A Sophi recebeu a confirmação.")
            st.rerun()

    # Produção e entrega — somente datas/status; nenhuma arte/foto é duplicada aqui.
    st.subheader("🏭 Produção e entrega")

    op = consultar("SELECT * FROM ordens_producao WHERE orcamento_id=? AND ativo='Sim' ORDER BY id DESC LIMIT 1", (oid,))
    data_producao = "A definir"
    data_prevista = data_br_segura(o.get("data_prevista_entrega")) or "A definir"
    hora_prevista = str(o.get("hora_prevista_entrega") or "").strip()

    if not op.empty:
        r = op.iloc[0]
        # A data de criação da OP é a única data disponível para indicar quando
        # a produção foi registrada. Não criamos/alteramos datas inexistentes.
        data_producao = data_br_segura(r.get("data_criacao")) or "A definir"
        data_prevista = data_br_segura(r.get("data_entrega") or o.get("data_prevista_entrega")) or "A definir"
        hora_prevista = str(r.get("hora_entrega") or o.get("hora_prevista_entrega") or "").strip()

    if hora_prevista:
        try:
            hora_dt = pd.to_datetime(hora_prevista, errors="coerce")
            hora_prevista = hora_dt.strftime("%H:%M") if pd.notna(hora_dt) else hora_prevista[:5]
        except Exception:
            hora_prevista = hora_prevista[:5]

    d1, d2 = st.columns(2)
    with d1:
        st.metric("Produção", data_producao)
    with d2:
        st.metric("Data de entrega", f"{data_prevista}{(' às '+hora_prevista) if hora_prevista else ''}")

    if not op.empty:
        r = op.iloc[0]
        st.caption(f"Status da produção: {r.get('status','Aguardando')}")

    ent = consultar("SELECT * FROM entregas WHERE referencia_tipo='OP' AND referencia_id IN (SELECT id FROM ordens_producao WHERE orcamento_id=?) AND ativo='Sim' ORDER BY id DESC LIMIT 1", (oid,))
    if not ent.empty:
        e=ent.iloc[0]
        data_ent=data_br_segura(e.get("data_entrega")) or "-"
        st.caption(f"Entrega: {e.get('tipo_entrega','-')} · {e.get('status','-')} · {data_ent}")

    st.subheader("📜 Histórico")
    hist = consultar("SELECT data,evento,descricao FROM portal_eventos WHERE orcamento_id=? ORDER BY id DESC LIMIT 100", (oid,))
    if hist.empty: st.info("O histórico será preenchido conforme o pedido avançar.")
    else:
        hist=hist.copy()
        if "data" in hist.columns: hist["data"]=hist["data"].apply(_formatar_data_hora_portal)
        st.dataframe(hist,use_container_width=True,hide_index=True)

    st.subheader("💬 Falar com a Sophi")
    whatsapp = obter_config("whatsapp", "")
    if whatsapp:
        import urllib.parse
        numero = "".join(c for c in str(whatsapp) if c.isdigit())
        link = f"https://wa.me/{numero}?text={urllib.parse.quote('Olá! Estou acompanhando meu pedido pelo Portal do Cliente. Pedido '+codigo+'.')}"
        st.link_button("💬 Falar com a Sophi no WhatsApp", link, use_container_width=True)


def gerar_pdf_orcamento_bytes(orcamento_id):
    from io import BytesIO
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.enums import TA_CENTER
    from reportlab.lib.units import mm

    o_df = consultar("SELECT * FROM orcamentos WHERE id=?", (int(orcamento_id),))
    if o_df.empty:
        return None
    o = o_df.iloc[0]
    itens = consultar("SELECT produto, categoria, quantidade, valor_unitario, desconto, total FROM orcamento_itens WHERE orcamento_id=?", (int(orcamento_id),))

    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, rightMargin=16*mm, leftMargin=16*mm, topMargin=16*mm, bottomMargin=16*mm)
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name='SophiTitle', parent=styles['Title'], alignment=TA_CENTER, fontSize=20, leading=24, spaceAfter=12))
    story = [Paragraph('SOPHI PERSONALIZADOS', styles['SophiTitle']), Paragraph('ORÇAMENTO', styles['Heading2']), Spacer(1, 6)]
    codigo = codigo_visual('ORC', int(o['id']), ano=datetime.now().year)
    story.append(Paragraph(f"<b>Orçamento:</b> {codigo}", styles['Normal']))
    story.append(Paragraph(f"<b>Cliente:</b> {html.escape(str(o.get('cliente_nome') or '-'))}", styles['Normal']))
    story.append(Paragraph(f"<b>Data:</b> {datetime.now().strftime('%d/%m/%Y')}", styles['Normal']))
    story.append(Spacer(1, 10))

    data = [['Produto', 'Categoria', 'Qtd.', 'Unitário', 'Desconto', 'Total']]
    if itens.empty:
        data.append(['Sem itens', '', '', '', '', real(float(o.get('total') or 0))])
    else:
        for _, r in itens.iterrows():
            data.append([
                str(r.get('produto') or '-'),
                str(r.get('categoria') or '-'),
                str(r.get('quantidade') or 0),
                real(float(r.get('valor_unitario') or 0)),
                real(float(r.get('desconto') or 0)),
                real(float(r.get('total') or 0)),
            ])
    tbl = Table(data, repeatRows=1, colWidths=[45*mm, 30*mm, 15*mm, 28*mm, 25*mm, 28*mm])
    tbl.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,0),colors.black),
        ('TEXTCOLOR',(0,0),(-1,0),colors.white),
        ('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),
        ('GRID',(0,0),(-1,-1),0.4,colors.grey),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('FONTSIZE',(0,0),(-1,-1),8),
        ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white, colors.HexColor('#f7f7f7')]),
        ('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),
    ]))
    story += [tbl, Spacer(1, 12), Paragraph(f"<b>TOTAL: {real(float(o.get('total') or 0))}</b>", styles['Heading2'])]
    story.append(Spacer(1, 12))
    story.append(Paragraph('Este orçamento foi preparado pela Sophi Personalizados Oficial.', styles['Normal']))
    doc.build(story)
    return buf.getvalue()


def tela_portal_cliente_admin():
    garantir_portal_v2()
    st.title("🌐 Portal do Cliente")
    st.caption("Envie o orçamento, disponibilize a arte e acompanhe as decisões do cliente em um único lugar.")

    orcs = consultar("SELECT id,cliente_nome,whatsapp,status,total,data_prevista_entrega FROM orcamentos ORDER BY id DESC LIMIT 500")
    if orcs.empty:
        st.info("Crie um orçamento primeiro para gerar o portal.")
        return

    mapa = {f"{codigo_visual('ORC', r['id'], ano=datetime.now().year)} · {r['cliente_nome']} · {real(r['total'])} · {r['status']}": int(r['id']) for _, r in orcs.iterrows()}
    esc = st.selectbox("Pedido / orçamento", list(mapa.keys()))
    oid = mapa[esc]
    o = orcs[orcs.id == oid].iloc[0]
    link = _portal_url_v2(oid)
    codigo = codigo_visual('ORC', oid, ano=datetime.now().year)

    c1, c2, c3 = st.columns(3)
    c1.metric("Cliente", str(o['cliente_nome']))
    c2.metric("Total", real(o['total']))
    c3.metric("Status", str(o['status']))

    st.markdown("### 1. Enviar orçamento + Portal")
    st.caption("O botão abre o WhatsApp com uma mensagem pronta e o link individual deste pedido. O PDF é baixado separadamente para você anexar à conversa.")

    msg = mensagem_portal_cliente(
        o['cliente_nome'], codigo, str(o['status']), real(o['total']), link
    )
    msg = st.text_area("Mensagem pronta para WhatsApp", value=msg, height=220, key=f"msg_portal_{oid}")

    try:
        pdf_bytes = gerar_pdf_orcamento_bytes(oid)
    except Exception as exc:
        pdf_bytes = None
        st.warning(f"Não foi possível gerar o PDF neste momento: {exc}")

    a, b = st.columns(2)
    with a:
        numero = "".join(x for x in str(o.get('whatsapp') or '') if x.isdigit())
        if numero:
            import urllib.parse
            wa_url = f"https://wa.me/{numero}?text={urllib.parse.quote(msg)}"
            st.link_button("📲 Enviar orçamento + Portal pelo WhatsApp", wa_url, use_container_width=True)
        else:
            st.button("📲 WhatsApp não cadastrado", disabled=True, use_container_width=True)
    with b:
        if pdf_bytes:
            st.download_button(
                "📄 Baixar orçamento em PDF",
                data=pdf_bytes,
                file_name=f"Orcamento_{codigo}.pdf",
                mime="application/pdf",
                use_container_width=True,
                key=f"pdf_orc_{oid}"
            )

    st.info("O WhatsApp abre com a mensagem e o link do Portal. Baixe o PDF e anexe manualmente à conversa.")

    st.markdown("### 2. 🎨 Arte para aprovação")
    st.caption("Coloque aqui a arte criada para este cliente. Ela ficará disponível no Portal para visualização, aprovação ou solicitação de alteração.")
    up = st.file_uploader(
        "Arte do cliente",
        type=["png", "jpg", "jpeg", "webp"],
        key=f"arte_upload_{oid}"
    )
    obs = st.text_input("Observação para o cliente (opcional)", key=f"arte_obs_{oid}")

    if up is not None:
        st.image(up, caption=up.name, use_container_width=True)

    if up and st.button("📤 Enviar arte para aprovação no Portal", type="primary", use_container_width=True, key=f"enviar_arte_{oid}"):
        try:
            UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
            safe_original = Path(up.name).name.replace(" ", "_")
            safe_name = f"portal_{oid}_{datetime.now().strftime('%Y%m%d%H%M%S')}_{safe_original}"
            path = UPLOAD_DIR / safe_name
            path.write_bytes(up.getbuffer())

            prev = consultar("SELECT COALESCE(MAX(versao),0) AS v FROM portal_artes WHERE orcamento_id=?", (oid,))
            vers = int(prev.iloc[0]['v'] or 0) + 1 if not prev.empty else 1

            # Não substitui automaticamente outras artes: um pedido pode ter várias artes válidas.
            executar(
                "INSERT INTO portal_artes(orcamento_id,nome_arquivo,caminho,versao,status,observacao) VALUES(?,?,?,?,?,?)",
                (oid, up.name, str(path), vers, 'Aguardando aprovação', obs)
            )
            portal_evento(oid, gerar_token_portal('Orçamento', oid), 'Arte enviada', f'Versão {vers} enviada para aprovação.')
            st.success(f"Arte versão {vers} enviada para o Portal do Cliente.")
            st.rerun()
        except Exception as exc:
            st.error(f"Não foi possível salvar a arte: {exc}")

    artes = consultar("SELECT id,versao,nome_arquivo,status,observacao,data,caminho FROM portal_artes WHERE orcamento_id=? ORDER BY id DESC", (oid,))
    if not artes.empty:
        artes_exib=artes.drop(columns=["caminho"],errors="ignore").copy()
        if "data" in artes_exib.columns: artes_exib["data"]=artes_exib["data"].apply(_formatar_data_hora_portal)
        st.dataframe(artes_exib,use_container_width=True,hide_index=True)

        st.caption("Você pode manter várias artes no mesmo pedido. Use excluir para remover uma arte enviada por engano ou substituir para colocar uma nova versão no lugar dela.")
        for _, arte_row in artes.iterrows():
            arte_id = int(arte_row["id"])
            versao = int(arte_row.get("versao") or 1)
            nome_arte = str(arte_row.get("nome_arquivo") or "Arte")
            status_arte = str(arte_row.get("status") or "")
            c_arte, c_sub, c_del = st.columns([4,3,1])
            with c_arte:
                st.markdown(f"**Versão {versao} — {html.escape(nome_arte)}** · {html.escape(status_arte)}")
            with c_sub:
                novo_up = st.file_uploader(
                    "Substituir arte",
                    type=["png","jpg","jpeg","webp"],
                    key=f"substituir_arte_upload_{oid}_{arte_id}",
                    label_visibility="collapsed"
                )
                if novo_up is not None and st.button("🔄 Substituir", key=f"substituir_arte_btn_{oid}_{arte_id}", use_container_width=True):
                    try:
                        UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
                        safe_original = Path(novo_up.name).name.replace(" ", "_")
                        safe_name = f"portal_{oid}_{datetime.now().strftime('%Y%m%d%H%M%S')}_{safe_original}"
                        novo_path = UPLOAD_DIR / safe_name
                        novo_path.write_bytes(novo_up.getbuffer())
                        prev = consultar("SELECT COALESCE(MAX(versao),0) AS v FROM portal_artes WHERE orcamento_id=?", (oid,))
                        nova_versao = int(prev.iloc[0]['v'] or 0) + 1 if not prev.empty else versao + 1
                        executar("UPDATE portal_artes SET status='Substituída' WHERE id=?", (arte_id,))
                        executar(
                            "INSERT INTO portal_artes(orcamento_id,nome_arquivo,caminho,versao,status,observacao) VALUES(?,?,?,?,?,?)",
                            (oid, novo_up.name, str(novo_path), nova_versao, 'Aguardando aprovação', str(arte_row.get('observacao') or ''))
                        )
                        portal_evento(oid, gerar_token_portal('Orçamento', oid), 'Arte substituída', f'Versão {versao} substituída pela versão {nova_versao}.')
                        st.success(f"Arte substituída pela versão {nova_versao}.")
                        st.rerun()
                    except Exception as exc:
                        st.error(f"Não foi possível substituir a arte: {exc}")
            with c_del:
                if st.button("🗑️", key=f"excluir_arte_{oid}_{arte_id}", help="Excluir esta arte do Portal do Cliente", use_container_width=True):
                    try:
                        caminho_excluir = str(arte_row.get("caminho") or "")
                        if caminho_excluir:
                            try:
                                Path(caminho_excluir).unlink(missing_ok=True)
                            except Exception:
                                pass
                        executar("DELETE FROM portal_artes WHERE id=?", (arte_id,))
                        portal_evento(oid, gerar_token_portal('Orçamento', oid), 'Arte excluída', f'Versão {versao} removida do Portal do Cliente.')
                        st.success(f"Arte versão {versao} excluída.")
                        st.rerun()
                    except Exception as exc:
                        st.error(f"Não foi possível excluir a arte: {exc}")
    else:
        st.info("Nenhuma arte enviada para este pedido ainda.")

    st.markdown("### 3. 📨 Decisões recebidas")
    aps = consultar("SELECT data,tipo,status,comentario FROM portal_aprovacoes WHERE orcamento_id=? ORDER BY id DESC", (oid,))
    if aps.empty:
        st.info("Nenhuma decisão recebida ainda.")
    else:
        aps_exib=aps.copy()
        if "data" in aps_exib.columns: aps_exib["data"]=aps_exib["data"].apply(_formatar_data_hora_portal)
        st.dataframe(aps_exib,use_container_width=True,hide_index=True)

    st.link_button("🌐 Abrir Portal do Cliente", link, use_container_width=True)





def garantir_calendario_comercial_profissional():
    """Cria apenas tabelas novas do Calendário Comercial; não altera tabelas existentes."""
    try:
        executar("""
        CREATE TABLE IF NOT EXISTS calendario_comercial_datas (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nome TEXT NOT NULL,
            data TEXT,
            categoria TEXT,
            oportunidade TEXT DEFAULT 'Média',
            quando_comecar INTEGER DEFAULT 30,
            divulgacao_dias INTEGER DEFAULT 30,
            encomendas_dias INTEGER DEFAULT 20,
            ideias_produtos TEXT,
            ideias_conteudo TEXT,
            checklist TEXT,
            ativo TEXT DEFAULT 'Sim'
        )
        """)
        executar("""
        CREATE TABLE IF NOT EXISTS calendario_comercial_campanhas (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nome TEXT NOT NULL,
            data_evento TEXT,
            inicio_planejamento TEXT,
            inicio_divulgacao TEXT,
            abertura_encomendas TEXT,
            prazo_final TEXT,
            meta REAL DEFAULT 0,
            produtos TEXT,
            status TEXT DEFAULT 'Planejada',
            observacoes TEXT,
            data_criacao TEXT DEFAULT CURRENT_TIMESTAMP
        )
        """)
    except Exception:
        pass


def _pascoa(ano):
    """Páscoa pelo algoritmo de Meeus/Jones/Butcher."""
    a = ano % 19; b = ano // 100; c = ano % 100; d = b // 4; e = b % 4
    f = (b + 8) // 25; g = (b - f + 1) // 3
    h = (19*a + b - d - g + 15) % 30; i = c // 4; k = c % 4
    l = (32 + 2*e + 2*i - h - k) % 7; m = (a + 11*h + 22*l) // 451
    mes = (h + l - 7*m + 114) // 31; dia = ((h + l - 7*m + 114) % 31) + 1
    return date(ano, mes, dia)


def _domingo_do_mes(ano, mes, numero=2):
    primeiro = date(ano, mes, 1)
    primeiro_dom = 1 + ((6 - primeiro.weekday()) % 7)
    return date(ano, mes, primeiro_dom + 7*(numero-1))


def _sexta_da_black_friday(ano):
    """Black Friday = 4ª sexta-feira de novembro."""
    nov1 = date(ano, 11, 1)
    primeira_sexta = 1 + ((4 - nov1.weekday()) % 7)
    return date(ano, 11, primeira_sexta + 21)



