        with st.form("form_imp"):
            nome=st.text_input("Nome da impressora"); modelo=st.text_input("Modelo"); largura=st.selectbox("Largura",["58 mm","80 mm","50×30 mm","100×150 mm"]); padrao=st.checkbox("Definir como padrão")
